// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {airPort} from "../src/airPort.sol";

contract InvMutTest is Test {
    airPort c;
    function setUp() public { c = new airPort(); }

    // Fuzzed parameters: from address (actor who would be passed as `from`), caddress (callee address), and a uint v
    // We only need to fuzz addresses and v; the distinguishing input is an empty array for _tos.
    function testFuzz_property(address fromAddr, address caddress, uint256 v) public {
        // Keep domain wide: no restrictive vm.assume. But avoid zero-address for `fromAddr` to be realistic
        if (fromAddr == address(0)) fromAddr = address(1);
        if (caddress == address(0)) caddress = address(2);

        // Prepare an empty recipients array which is the critical distinguishing input between reference and mutant
        address[] memory tos = new address[](0);

        // Call and observe whether the call reverts or not. The correct contract MUST revert for empty _tos.
        bool ok;
        try c.transfer(fromAddr, caddress, tos, v) {
            ok = true;
        } catch {
            ok = false;
        }

        // The universal property: for ANY admissible inputs, calling transfer with an empty _tos MUST revert (ok == false)
        // The mutant that uses require(_tos.length >= 0) will return true (ok == true) for some inputs (empty _tos),
        // causing this assertion to fail on that mutant.
        assertTrue(!ok);
    }
}
